import {EXPEDITION_NAME,EXPEDITION_LENGTH,EXPEDITION_STARTER,expeditionField} from './expedition-data.mjs';
import {terrainProfilePoints} from './campaign-atlas-model.mjs';
import {encounterEnemyIntel} from './enemy-intel.mjs';
const escape=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const number=value=>Number(value).toLocaleString();
export function expeditionLaunchLabel(run,{started=false,summary=null}={}){
 if(run.complete)return 'Archive and start new charter';
 if(run.choosing)return run.choices.length===1?'Prepare the final march':'Choose your next road';
 if(summary?.outcome==='defeat')return `Retry ${run.current.name}`;
 return `${started?'Resume':'Start'} ${run.current.name}`;
}
export function expeditionResultCopy(run,battle){
 const won=battle.summary?.outcome==='victory';
 return {title:run.complete?'Charter complete':won?'Road secured':'The march was stopped',
  description:run.complete?`Four fields won. Your route through ${run.state.path.map(id=>expeditionField(id).name).join(', ')} is recorded in this charter.`:won?`${run.current.name} is won. Choose your next road, then prepare your army.`:'Keep your combat earnings. You can adjust the loadout and retry the same field.',
  action:expeditionLaunchLabel(run,{summary:battle.summary})};
}
export function renderExpeditionReceipt(host,run){
 const result=run?.state.lastResult;
 if(!result){host.innerHTML='';return;}
 host.innerHTML=`<div class="campaign-reward-heading"><span class="eyebrow">${EXPEDITION_NAME.toUpperCase()} · LEG ${run.current.leg} / ${EXPEDITION_LENGTH}</span><strong>${escape(run.current.name)}</strong><p>${run.complete?'Every leg is complete. Export this charter to keep the route and record.':run.choosing?(run.choices.length===1?'The final march to Storm Crown is open.':'Two roads, different threats. Your next choice becomes part of this run.'):'The same company and terrain await your retry.'}</p></div><div class="campaign-reward-ledger"><span>Combat gold<b>+${number(result.stats.goldEarned)}</b></span><span>Victory bonus<b>+${number(result.gold)}</b></span><span>Army spending<b>−${number(result.stats.goldSpent)}</b></span><span>Bonus XP<b>+${number(result.xp)}</b></span></div>`;
}
export function createExpeditionRoute({host,getRun,getState,onChoose,onReturn,onRestart}){
 let confirmingReset=false;
 const render=()=>{
  const run=getRun(),state=getState(),field=run.current,canChoose=run.choosing&&!state.pendingOutcome;
  const targets=encounterEnemyIntel({level:field.level,difficulty:run.profile.difficulty,types:Object.keys(field.counts)});
  host.innerHTML=`<div class="charter-banner"><div><span class="eyebrow">FOUR LEGS · SIX FIELDS · FOUR POSSIBLE ROUTES</span><h3>${EXPEDITION_NAME}</h3><p>March with a chartered army. Choose the route that suits your cards, then earn your way to Storm Crown.</p></div><div class="charter-seed"><span>Charter seed</span><strong>${run.state.seed}</strong><small>Retained on save and retry</small></div></div>
   <ol class="charter-progress" aria-label="Chosen expedition route">${Array.from({length:EXPEDITION_LENGTH},(_,i)=>{const id=run.state.path[i],done=i<run.state.cleared;return `<li data-state="${done?'complete':id?'current':'unknown'}"><span>${done?'✓':i+1}</span><strong>${id?expeditionField(id).name:i===3?'Storm Crown':'Road to choose'}</strong><small>${done?'Won':id?'Current field':i===3?'Final siege':'Unchosen'}</small></li>`;}).join('')}</ol>
   ${canChoose?`<section class="charter-choices" aria-labelledby="charterChoiceTitle"><div><span class="eyebrow">LEG ${field.leg+1}</span><h3 id="charterChoiceTitle">Choose your next road</h3><p>The chosen field becomes the next leg. The other road remains for a future charter.</p></div><div class="charter-choice-grid">${run.choices.map(choice=>`<article><span class="eyebrow">${choice.objective==='break-keep'?'SIEGE OBJECTIVE':'FLAG OR ELIMINATION'}</span><h4>${choice.name}</h4><p>${choice.description}</p><p class="charter-tradeoff">${choice.tradeoff}</p><div class="charter-choice-facts"><span>${Object.values(choice.counts).reduce((n,c)=>n+c,0)} enemies</span><span>${number(choice.enemyKeepHP)} keep HP</span></div><button data-charter-choice="${choice.id}" class="primary">Take this road</button></article>`).join('')}</div></section>`:''}
   <div class="charter-current"><section><span class="eyebrow">${run.complete?'FINAL FIELD WON':canChoose?'FIELD JUST WON':'CURRENT FIELD'} · LEG ${field.leg}</span><h3>${field.name}</h3><p>${field.description}</p><div class="atlas-terrain"><svg viewBox="0 0 600 145" preserveAspectRatio="none" role="img" aria-label="Authored expedition terrain profile"><polyline points="${terrainProfilePoints(field.heights)}"/><path d="M105 5v130M540 5v130"/></svg><div><span>Your keep</span><span>Authored terrain</span><span>Enemy keep</span></div></div><div class="atlas-objective"><h4>${field.objective==='break-keep'?'Break the keep':'Flag or elimination'}</h4><p>${field.objectiveText}</p><small>Your hero must survive. The enemy returning your home flag still loses the field.</small></div><p class="charter-tradeoff">${field.tradeoff}</p></section><section><h4>Known enemy company</h4><p class="atlas-stat-note">Fixed composition. Spawn HP at ${run.profile.difficulty} difficulty; existing enemies retain their spawn stats.</p><div class="atlas-threats">${targets.map(enemy=>`<span><b>${enemy.name} ×${field.counts[enemy.id]}</b><small>${number(Math.round(enemy.maxHp))} HP</small></span>`).join('')}</div><details class="charter-counters"><summary>Enemy counters</summary>${targets.map(enemy=>`<p><strong>${enemy.name}:</strong> ${enemy.counter}</p>`).join('')}</details><details class="charter-starter"><summary>Charter rules and starting kit</summary><p>Each new banner starts at hero rank ${EXPEDITION_STARTER.rank} with ${number(EXPEDITION_STARTER.gold)} gold, Basic Arrow rank ${EXPEDITION_STARTER.basicRank}, and six rank ${EXPEDITION_STARTER.skillRank} cards: Grunt, Archer, Fire Arrow, Ice Arrow, Bomb Arrow and Flak Bomb Arrow. These are the expedition’s declared starting supplies.</p><p>Army costs, damage, skill progression and victory bonuses use normal combat rules. This charter has its own gold, cards and records. Nothing transfers to the Crownroad or practice sessions.</p><p>Save a charter code or file before closing. Live fields restart on load; settled results and choices are preserved without paying rewards again. Retrying keeps combat earnings and uses the same encounter seed.</p></details></section></div>
   <footer class="atlas-actions"><p role="status">${state.started&&!state.summary?'Your live battlefield is paused. The route cannot change until this field is won.':run.complete?'All four legs are complete. Keep a save, or archive the banner and begin again from the lobby.':run.choosing?'Choose one route above. Combat will wait for Start in the lobby.':'Review the current field, then Start from the lobby when ready.'}</p><button id="charterReturn" class="primary">Back to lobby</button><button id="charterRestart" class="danger-link">Restart charter</button></footer>
   <div id="charterResetConfirm" class="confirmation-inline ${confirmingReset?'':'hidden'}"><p>Replace this banner’s charter with a fresh run? Its gold, cards and chosen route will be discarded. Export first to keep it. Other banners and play sessions are preserved.</p><div class="overlay-actions"><button id="cancelCharterReset" class="primary">Keep this charter</button><button id="confirmCharterReset" class="danger-link">Restart with starting supplies</button></div></div>`;
  for(const button of host.querySelectorAll('[data-charter-choice]'))button.onclick=()=>{if(getRun().choosing)onChoose(button.getAttribute('data-charter-choice'));};
  host.querySelector('#charterReturn').onclick=onReturn;
  host.querySelector('#charterRestart').onclick=()=>{confirmingReset=true;render();host.querySelector('#cancelCharterReset')?.focus?.();};
  host.querySelector('#cancelCharterReset').onclick=()=>{confirmingReset=false;render();host.querySelector('#charterRestart')?.focus?.();};
  host.querySelector('#confirmCharterReset').onclick=()=>{if(!confirmingReset)return;confirmingReset=false;onRestart();};
 };
 return {open(){confirmingReset=false;render();},refresh:render,cancelReset(){if(!confirmingReset)return false;confirmingReset=false;render();return true;}};
}
